-- Step 4: verify what was actually written, or roll the whole thing back
DO $$
DECLARE v_periods INT; v_records INT; v_gross NUMERIC; v_net NUMERIC;
        v_pgross NUMERIC; v_pnet NUMERIC;
BEGIN
  SELECT count(*) INTO v_periods FROM payroll_periods WHERE month = 6 AND year = 2026;
  SELECT count(*), COALESCE(round(sum(r.total_gross)::numeric, 2), 0),
         COALESCE(round(sum(r.net_salary)::numeric, 2), 0)
    INTO v_records, v_gross, v_net
    FROM payroll_records r JOIN payroll_periods p ON p.id = r.period_id
   WHERE p.month = 6 AND p.year = 2026;
  IF v_periods <> 23 THEN
    RAISE EXCEPTION 'period count is %, expected 23', v_periods;
  END IF;
  IF v_records <> 2033 THEN
    RAISE EXCEPTION 'record count is %, expected 2033', v_records;
  END IF;
  IF v_gross <> 11247331.13 THEN
    RAISE EXCEPTION 'gross total is %, expected 11247331.13', v_gross;
  END IF;
  IF v_net <> 10956468.72 THEN
    RAISE EXCEPTION 'net total is %, expected 10956468.72', v_net;
  END IF;
  SELECT round(sum(total_gross)::numeric, 2), round(sum(total_net)::numeric, 2)
    INTO v_pgross, v_pnet
    FROM payroll_periods WHERE month = 6 AND year = 2026;
  IF v_pgross <> 11247331.26 OR v_pnet <> 10956468.85 THEN
    RAISE EXCEPTION 'site totals are % / %, expected 11247331.26 / 10956468.85',
      v_pgross, v_pnet;
  END IF;
  RAISE NOTICE 'يونيو 2026: % periods, % records, gross %, net %',
    v_periods, v_records, v_gross, v_net;
END $$;

COMMIT;
